<script lang="ts">
  import {focusTrap} from '#lib/client/focus-trap.ts';
  import {onMount,tick} from 'svelte';import {page} from '$app/state';import {refreshAll,goto} from '$app/navigation';import type {AppData,Row} from '#lib/client/types.ts';import {command,display,recordName,displayTimestamp} from '#lib/client/api.ts';import {initializeTime,reconcileTimeCorrections,saveOfflineAssignments,getLocalTime,enqueueTime,syncTime,durationSeconds,durationLabel,type LocalTimeState,type LocalSegment,type LocalReceipt,type TimeOperation} from '#lib/client/offline-time.ts';import Icon from './Icon.svelte';import Status from './Status.svelte';import TimeReview from './TimeReview.svelte';import WorkReport from './WorkReport.svelte';import TimeSessionHistory from './TimeSessionHistory.svelte';
  let {data}:{data:AppData}=$props();let timerState:LocalTimeState|null=$state(null);let receipts:LocalReceipt[]=$state([]);let now=$state(Date.now());let busy=$state(false);let syncing=$state(false);let error=$state('');let notice=$state('');let orderId=$state('');let activity=$state('Allgemeines');let showSwitch=$state(false);let showManual=$state(false);let showCorrection=$state(false);let manualFrom=$state('');let manualTo=$state('');let manualPauses:{id:string;from:string;to:string}[]=$state([]);let manualAllocations:{id:string;from:string;to:string;order_id:string;activity:string}[]=$state([]);let pausesReviewed=$state(false);let correctionSource:Row|null=$state(null);let manualNote=$state('');let correctionReason=$state('');let day=$state(initialDay());let online=$state(true);let ready=$state(false);let storagePersistent=$state(false);let reload:()=>Promise<void>;
  const pending=$derived(receipts.filter(r=>!['confirmed','resolved'].includes(r.sync_status)));const conflicts=$derived(receipts.filter(r=>r.sync_status==='conflict'||r.sync_status==='unauthorized'));const conflictGroups=$derived([...new Set(conflicts.map(c=>c.time_session_id))]);const resolvedReceipts=$derived(receipts.filter(c=>c.sync_status==='resolved'));const elapsed=$derived.by(()=>timerState?durationSeconds(timerSegments,now):0);const breakSeconds=$derived.by(()=>timerState?durationSeconds(timerSegments,now,'break'):0);const orders=$derived(data.lookups?.orders||[]);const allocations=$derived(data.related?.time_allocations||data.related?.allocations||[]);
  function businessDate(value:any){if(!value)return '';const date=new Date(value);return Number.isFinite(date.getTime())?new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin'}).format(date):'';}
  function initialDay(){const selected=page.url.searchParams.get('date');return selected&&/^\d{4}-\d{2}-\d{2}$/.test(selected)?selected:businessDate(new Date());}
  const effectiveCorrections=$derived((data.related?.time_corrections||[]).filter(c=>c.status==='approved'&&c.session_id&&c.new_snapshot?.segments).filter((c,index,all)=>all.findIndex(other=>other.session_id===c.session_id)===index));
  function correctedSegments(correction:Row):LocalSegment[]{const snapshot=correction.new_snapshot;return snapshot.segments.map((segment:Row,index:number):LocalSegment=>{const matches=(snapshot.allocations||[]).filter((a:Row)=>Date.parse(a.started_at)<Date.parse(segment.ended_at)&&Date.parse(a.ended_at)>Date.parse(segment.started_at));const orders=[...new Set(matches.map((a:Row)=>a.order_id))];return {id:correction.id+':'+index,kind:segment.kind==='break'?'break':'work',start_at:segment.started_at,end_at:segment.ended_at,order_id:orders.length===1?orders[0] as string:null,activity:matches.length===1?matches[0].activity:orders.length>1?'Mehrere Arbeitszuordnungen':''};});}
  const timerSegments=$derived.by(()=>{const correction=effectiveCorrections.find(c=>c.session_id===timerState?.session_id);return correction?correctedSegments(correction):timerState?.segments||[];});
  $effect(()=>{const selected=page.url.searchParams.get('date');day=selected&&/^\d{4}-\d{2}-\d{2}$/.test(selected)?selected:businessDate(new Date());});
  const daySegments=$derived.by(()=>{const server=(data.related?.time_segments||[]).filter((s:Row)=>s.time_session_id!==timerState?.session_id&&!effectiveCorrections.some(c=>c.session_id===s.time_session_id)).map((s:Row)=>({id:s.id,kind:s.kind,start_at:s.started_at||s.start_at,end_at:s.ended_at||s.end_at||null,order_id:s.order_id||allocations.find((a:Row)=>a.time_segment_id===s.id)?.order_id||null,activity:s.activity||allocations.find((a:Row)=>a.time_segment_id===s.id)?.activity||''}));return [...server,...effectiveCorrections.filter(c=>c.session_id!==timerState?.session_id).flatMap(correctedSegments),...timerSegments].filter(s=>businessDate(s.start_at)===day).sort((a,b)=>Date.parse(a.start_at)-Date.parse(b.start_at));});
  const submissionIds=$derived.by(()=>{const sessions=(data.related?.time_sessions||[]).filter((s:Row)=>businessDate(s.started_at)===day&&s.status==='finished').map((s:Row)=>s.id);const current=(data.related?.time_sessions||[]).find((s:Row)=>s.id===timerState?.session_id);if(timerState?.status==='finished'&&businessDate(timerState.started_at)===day&&!['submitted','approved'].includes(current?.status))sessions.push(timerState.session_id);return [...new Set(sessions.filter(Boolean))];});
  const dayAllocations=$derived([...allocations.filter((a:Row)=>!effectiveCorrections.some(c=>c.session_id===a.time_session_id)),...effectiveCorrections.flatMap(c=>c.new_snapshot.allocations||[])].filter((allocation:Row)=>businessDate(allocation.started_at||allocation.start_at)===day));
  const selectedDayRunning=$derived.by(()=>!!timerState&&businessDate(timerState.started_at)===day&&['work','break'].includes(timerState.status));
  async function selectDay(){if(!online){notice='Ohne Netz sehen Sie die bereits auf diesem Gerät verfügbaren Tage.';return;}await goto('/time?date='+encodeURIComponent(day),{reset:false});}
  onMount(()=>{if(!data.user)return;let stopped=false;const userId=data.user.id;reload=async()=>{const local=await getLocalTime(userId);if(stopped)return;timerState=local.state;receipts=local.commands;if(!orderId)orderId=local.state.order_id||data.summary?.todayOrder?.id||'';};const sync=async()=>{if(stopped)return;try{await synchronize();}catch{/* Local recordings remain pending until focus, online or manual retry. */}};const init=async()=>{try{await reconcileTimeCorrections(userId,data.related?.time_corrections||[]);const local=await initializeTime(userId,data.summary?.timeSession,data.related?.time_segments||[]);if(stopped)return;timerState=local.state;receipts=local.commands;orderId=local.state.order_id||data.summary?.todayOrder?.id||'';activity=display(local.state.activity||'general','activity');ready=true;if(data.summary?.offlineOrders)await saveOfflineAssignments(userId,data.summary.offlineOrders);if(navigator.storage?.persisted)storagePersistent=await navigator.storage.persisted();sync();}catch(e){error=e instanceof Error?e.message:'Der lokale Speicher ist nicht verfügbar.';}};init();const tick=setInterval(()=>now=Date.now(),1000);const focus=()=>{reload();sync();};const connection=()=>{online=navigator.onLine;if(online)sync();};window.addEventListener('focus',focus);window.addEventListener('online',connection);window.addEventListener('offline',connection);online=navigator.onLine;let channel:BroadcastChannel|undefined;try{channel=new BroadcastChannel(`schubert-time:${userId}`);channel.onmessage=()=>reload();}catch{}return()=>{stopped=true;clearInterval(tick);window.removeEventListener('focus',focus);window.removeEventListener('online',connection);window.removeEventListener('offline',connection);channel?.close();};});
  async function manualSync(){try{await synchronize();await refreshAll();await tick();if(data.user){await reconcileTimeCorrections(data.user.id,data.related?.time_corrections||[]);await reload();}notice='Der aktuelle Übertragungs- und Klärungsstand wurde geladen.';}catch(e){error=e instanceof Error?e.message:'Der Stand konnte nicht aktualisiert werden.';}}
  async function synchronize(){if(!data.user||syncing)return;syncing=true;try{const local=await syncTime(data.user.id);timerState=local.state;receipts=local.commands;online=true;}catch(e){notice=e instanceof Error?e.message:'Übertragung ausstehend.';throw e;}finally{syncing=false;}}
  async function operate(operation:TimeOperation){if(!data.user||busy||!ready)return;busy=true;error='';notice='';try{const result=await enqueueTime(data.user.id,operation,['start','switch'].includes(operation)?{order_id:orderId||null,activity}:{order_id:timerState?.order_id||null,activity:timerState?.activity||activity});timerState=result.state;now=Date.now();await reload();showSwitch=false;notice='Auf diesem Gerät gespeichert.';synchronize().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Die Zeit wurde nicht gespeichert. Bitte versuchen Sie es erneut oder erfassen Sie sie manuell.';}finally{busy=false;}}
  async function persist(){try{storagePersistent=await navigator.storage.persist();notice=storagePersistent?'Dauerhafter Browserspeicher wurde gewährt.':'Der Browser hat dauerhaften Speicher nicht gewährt. Übertragen Sie Zeiten zeitnah.';}catch{notice='Die Speichereinstellung wird von diesem Browser nicht unterstützt.';}}
  async function submitDay(){if(!data.user||busy)return;busy=true;error='';try{if(pending.length){await synchronize();if((await getLocalTime(data.user.id)).commands.some(c=>!['confirmed','resolved'].includes(c.sync_status)))throw new Error('Bitte klären oder synchronisieren Sie zuerst die ausstehenden Aufzeichnungen.');}await command('workforce.time.submit',undefined,{date:day,session_ids:submissionIds});notice='Der Tag wurde zur Prüfung eingereicht.';await refreshAll().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Einreichen fehlgeschlagen.';}finally{busy=false;}}
  function localInput(value:any){if(!value)return '';const date=new Date(value);return Number.isFinite(date.getTime())?new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,19):'';}
  function openManual(){correctionSource=null;manualFrom='';manualTo='';manualPauses=[];manualAllocations=[];pausesReviewed=false;manualNote='';showManual=true;showCorrection=false;error='';}
  function openCorrection(session:Row=data.summary?.timeSession||{id:timerState?.session_id,version:timerState?.version,started_at:timerState?.started_at,ended_at:timerState?.finished_at}){const prior=(data.related?.time_corrections||[]).find(c=>c.session_id===session.id&&c.status==='approved');const snapshot=prior?.new_snapshot;const actual=snapshot?.session||session;correctionSource=session;manualFrom=localInput(actual.started_at);manualTo=localInput(actual.ended_at);const intervals=session.local_segments||snapshot?.segments||(data.related?.time_segments||[]).filter(s=>s.time_session_id===session.id);manualPauses=intervals.filter((s:Row)=>s.kind==='break').sort((a:Row,b:Row)=>Date.parse(a.started_at||a.start_at)-Date.parse(b.started_at||b.start_at)).map((s:Row)=>({id:crypto.randomUUID(),from:localInput(s.started_at||s.start_at),to:localInput(s.ended_at||s.end_at)}));manualAllocations=[...(session.local_allocations||snapshot?.allocations||(data.related?.time_allocations||[]).filter(a=>a.time_session_id===session.id))].sort((a:Row,b:Row)=>Date.parse(a.started_at)-Date.parse(b.started_at)).map((a:Row)=>({id:crypto.randomUUID(),from:localInput(a.started_at),to:localInput(a.ended_at),order_id:a.order_id||'',activity:display(a.activity||'general','activity')}));orderId=session.current_order_id||orderId;activity=session.current_activity||activity;pausesReviewed=false;manualNote=session.notes||'';correctionReason='';showManual=true;showCorrection=true;error='';}
  function conflictSource(sessionId:string){const raw=receipts.filter(c=>c.time_session_id===sessionId).sort((a,b)=>a.client_sequence-b.client_sequence);const segments:Row[]=[];let active:Row|null=null;let started:string|null=null;let ended:string|null=null;let currentOrder:string|null=null;let currentActivity='';for(const receipt of raw){const operation=receipt.command_name.replace('workforce.time.','');if(operation==='start'){started=receipt.occurred_at;currentOrder=receipt.payload.order_id||null;currentActivity=receipt.payload.activity||'';}if(active){active.ended_at=receipt.occurred_at;segments.push(active);active=null;}if(operation==='finish'){ended=receipt.occurred_at;continue;}if(receipt.payload.order_id!==undefined)currentOrder=receipt.payload.order_id||null;if(receipt.payload.activity!==undefined)currentActivity=receipt.payload.activity;active={kind:operation==='pause'?'break':'work',started_at:receipt.occurred_at,ended_at:null,order_id:currentOrder,activity:currentActivity};}if(active)segments.push(active);return {id:sessionId,started_at:started,ended_at:ended,current_order_id:currentOrder,current_activity:currentActivity,local_segments:segments,local_allocations:segments.filter(segment=>segment.kind==='work'&&segment.ended_at).map(segment=>({started_at:segment.started_at,ended_at:segment.ended_at,order_id:segment.order_id,activity:segment.activity})),notes:''};}
  async function manual(event:SubmitEvent){event.preventDefault();busy=true;error='';try{const from=new Date(manualFrom);const to=new Date(manualTo);if(!Number.isFinite(from.getTime())||!Number.isFinite(to.getTime())||to<=from)throw new Error('Bitte geben Sie einen gültigen Zeitraum mit Ende nach dem Beginn ein.');if(!pausesReviewed)throw new Error('Bestätigen Sie bitte, dass alle tatsächlichen Pausen vollständig angegeben sind.');const breaks=manualPauses.map(p=>({started_at:new Date(p.from).toISOString(),ended_at:new Date(p.to).toISOString()})).sort((a,b)=>Date.parse(a.started_at)-Date.parse(b.started_at));let previousEnd=from.getTime();for(const pause of breaks){const start=Date.parse(pause.started_at),end=Date.parse(pause.ended_at);if(start<previousEnd||end<=start||end>to.getTime())throw new Error('Pausen müssen innerhalb der Arbeitszeit liegen, ein späteres Ende haben und dürfen sich nicht überschneiden.');previousEnd=end;}if(showCorrection&&correctionReason.trim().length<5)throw new Error('Beschreiben Sie bitte den Grund der Korrektur mit mindestens fünf Zeichen.');const allocations=showCorrection&&manualAllocations.length?manualAllocations.map(a=>({started_at:new Date(a.from).toISOString(),ended_at:new Date(a.to).toISOString(),order_id:a.order_id||null,activity:a.activity})):undefined;const originals=receipts.filter(c=>c.time_session_id===(correctionSource?.id||timerState?.session_id)&&!['confirmed','resolved'].includes(c.sync_status));const snapshot={started_at:from.toISOString(),ended_at:to.toISOString(),breaks,order_id:orderId||null,activity,allocations};await command(showCorrection?'workforce.time.propose_correction':'workforce.time.manual',showCorrection?correctionSource?.id||timerState?.session_id||undefined:undefined,{...snapshot,reason:showCorrection?correctionReason:manualNote,new_snapshot:showCorrection?snapshot:undefined,original_command_ids:originals.map(c=>c.command_id),original_commands:originals.map(({sync_status,error,result,received_at,attempts,resolution,...raw})=>raw),timezone:'Europe/Berlin'},showCorrection?correctionSource?.version:undefined);notice=showCorrection?'Der Korrekturantrag wurde gespeichert. Die Originalaufzeichnungen bleiben erhalten.':'Die nacherfasste Zeit wurde gespeichert.';showManual=false;showCorrection=false;await refreshAll().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Nacherfassung fehlgeschlagen.';}finally{busy=false;}}

</script>
<div class="page-heading"><div><h1>Meine Arbeitszeit</h1><p>Arbeit und Pausen schnell erfassen. Aufträge können Sie auch später zuordnen.</p></div><div class="page-heading-actions"><button class="btn" onclick={openManual}><Icon name="plus" size={16}/>Zeit nachtragen</button><button class="btn" disabled={syncing} onclick={manualSync}><Icon name="refresh" size={16} class={syncing?'spin':''}/>{syncing?'Wird übertragen …':'Synchronisieren'}</button></div></div>
{#if error}<div class="notice error" role="alert"><Icon name="alert"/><div>{error}</div></div>{/if}{#if notice}<div class="notice info" role="status"><Icon name={pending.length?'clock':'check'}/><div>{notice}</div></div>{/if}
{#if data.connected&&data.context?.employeeId===null}<div class="notice warning"><Icon name="users"/><div>Ihr Zugang ist noch keinem Beschäftigtenprofil zugeordnet. Die Verwaltung muss diese Zuordnung für die serverseitige Bestätigung ergänzen. Lokale tatsächliche Aufzeichnungen bleiben erhalten.</div></div>{/if}
{#if !online}<div class="notice warning"><Icon name="offline"/><div>Sie arbeiten ohne bestätigte Serververbindung. Start, Pause, Wechsel und Feierabend werden auf diesem Gerät gespeichert und später übertragen.</div></div>{/if}
<div class="time-grid"><div class="stack"><section class="timer-panel"><div class="timer-topline"><span class="eyebrow">{timerState?.status==='work'?'Arbeit läuft':timerState?.status==='break'?'Sie machen Pause':timerState?.status==='finished'?'Arbeitstag beendet':'Bereit für Ihren Arbeitstag'}</span><Status value={pending.length?'pending':receipts.find(c=>c.command_id===timerState?.last_command_id)?.sync_status==='resolved'?'resolved':'confirmed'}/></div><div class="timer-readout" aria-label={`${Math.floor(elapsed/3600)} Stunden ${Math.floor(elapsed%3600/60)} Minuten Arbeitszeit`}>{durationLabel(elapsed)}</div><p class="timer-description">{timerState?.started_at?`Beginn ${display(timerState.started_at,'start_at')} · Pause ${durationLabel(breakSeconds)}`:'Wählen Sie bei Bedarf einen Auftrag und starten Sie die Arbeit. Erfassen Sie jede tatsächliche Pause über „Pause“.'}</p>
  <div class="timer-actions">{#if !ready}<button class="btn primary large" disabled><Icon name="refresh" class="spin"/>Zeitspeicher wird geöffnet …</button>{:else if showSwitch}<button class="btn primary large" disabled={busy} onclick={()=>operate('switch')}>Auftrag wechseln<Icon name="arrow"/></button><button class="btn large" onclick={()=>showSwitch=false}>Abbrechen</button>{:else if timerState?.status==='work'}<button class="btn primary large" disabled={busy} onclick={()=>operate('pause')}><Icon name="pause"/>Pause</button><button class="btn large" disabled={busy} onclick={()=>showSwitch=true}><Icon name="briefcase"/>Wechseln</button><button class="btn large" disabled={busy} onclick={()=>operate('finish')}><Icon name="stop"/>Feierabend</button>{:else if timerState?.status==='break'}<button class="btn primary large" disabled={busy} onclick={()=>operate('resume')}><Icon name="play"/>Weiterarbeiten</button><button class="btn large" disabled={busy} onclick={()=>operate('finish')}><Icon name="stop"/>Feierabend</button>{:else}<button class="btn primary large full" disabled={busy} onclick={()=>operate('start')}><Icon name="play"/>Arbeit starten</button>{/if}</div>{#if !['work','break'].includes(timerState?.status||'')||showSwitch}<div class="field-grid"><div class="field"><label for="time-order">Auftrag</label><select id="time-order" bind:value={orderId}><option value="">Auftrag später zuordnen</option>{#each orders as order}<option value={order.id}>{order.name}</option>{/each}</select></div><div class="field"><label for="time-activity">Tätigkeit</label><select id="time-activity" bind:value={activity}>{#each ['Aufmaß','Bearbeitung / Werkstatt','Laden / Transport','Anfahrt','Montage','Nacharbeit','Allgemeines'] as item}<option value={item}>{item}</option>{/each}</select></div></div>{:else}<div class="action-preview" style="margin-bottom:0"><h3>{orders.find(o=>o.id===timerState?.order_id)?.name||'Noch keinem Auftrag zugeordnet'}</h3><p class="small">{display(timerState?.activity||'general','activity')}</p></div>{/if}
  <div class="timer-status"><Icon name={pending.length?'clock':'check'} size={14}/>{pending.length?`${pending.length} Aufzeichnung(en) noch nicht bestätigt`:'Alle lokalen Aufzeichnungen sind übertragen oder geklärt'}{timerState?.last_server_at?` · Letzter Abgleich ${new Intl.DateTimeFormat('de-DE',{hour:'2-digit',minute:'2-digit'}).format(new Date(timerState.last_server_at))}`:''}</div></section>
  <section class="panel"><header class="panel-header"><h2>Tagesverlauf</h2><div class="field"><label class="sr-only" for="time-day">Tag auswählen</label><input id="time-day" type="date" bind:value={day} onchange={selectDay}/></div></header><div class="panel-body">{#if effectiveCorrections.some(c=>businessDate(c.new_snapshot.session?.started_at)===day)}<p class="field-help mb">Dieser Verlauf zeigt die freigegebenen Korrekturen. Die unveränderten Originalaufzeichnungen können Sie in der jeweiligen Sitzung darunter öffnen.</p>{/if}{#each daySegments as segment}<div class="time-segment"><div class="segment-kind" class:break={segment.kind==='break'}><Icon name={segment.kind==='break'?'pause':'briefcase'} size={16}/></div><div class="segment-info"><strong>{segment.kind==='break'?'Pause':orders.find(o=>o.id===segment.order_id)?.name||'Arbeit · Zuordnung offen'}</strong><p>{displayTimestamp(segment.start_at)} – {segment.end_at?displayTimestamp(segment.end_at):'läuft'}{segment.activity?` · ${display(segment.activity,'activity')}`:''}</p></div><span class="segment-duration">{durationLabel(durationSeconds([segment],now,segment.kind))}</span></div>{/each}{#if !daySegments.length}<div class="empty-state compact"><div class="empty-icon"><Icon name="clock"/></div><h3>Für diesen Tag noch keine Zeit</h3><p>Starten Sie Ihre Arbeit oben oder tragen Sie einen bereits geleisteten Zeitraum nach.</p></div>{/if}</div><footer class="panel-footer"><span class="small muted">Prüfen Sie Tätigkeit, Zuordnung und tatsächliche Pausen.</span><button class="btn primary" disabled={busy||selectedDayRunning||!submissionIds.length} onclick={submitDay}>Tag prüfen & abgeben<Icon name="arrow" size={16}/></button></footer></section>
  {#if dayAllocations.length}<section class="panel"><header class="panel-header"><h2>Bestätigte Auftragszuordnung</h2></header><div class="table-scroll"><table class="data-table"><thead><tr><th>Auftrag</th><th>Tätigkeit</th><th>Von</th><th>Bis</th></tr></thead><tbody>{#each dayAllocations as allocation}<tr><td>{display(allocation.order_id,'order_id',data)}</td><td>{display(allocation.activity||'general','activity')}</td><td>{display(allocation.started_at||allocation.start_at,'start_at')}</td><td>{display(allocation.ended_at||allocation.end_at,'end_at')}</td></tr>{/each}</tbody></table></div></section>{/if}
  <TimeSessionHistory {data} {day} oncorrect={openCorrection}/><WorkReport {data} initialOrderId={orderId} {activity}/><TimeReview {data}/></div><aside class="stack"><section class="panel"><header class="panel-header"><h2>Übertragung & Klärung</h2><span class="count">{pending.length}</span></header><div class="panel-body">{#each pending as receipt}<div class="sync-row"><strong>{receipt.command_name.replace('workforce.time.','')==='start'?'Arbeit starten':receipt.command_name.endsWith('pause')?'Pause':receipt.command_name.endsWith('resume')?'Weiterarbeit':receipt.command_name.endsWith('switch')?'Auftragswechsel':'Feierabend'}</strong><div class="sync-details"><span>{display(receipt.occurred_at,'occurred_at')}</span><Status value={receipt.sync_status}/></div>{#if receipt.error}<p class="small mt">{typeof receipt.error==='string'?receipt.error:receipt.error.message}</p>{/if}</div>{/each}{#if !pending.length}<p class="small">Keine ausstehenden Übertragungen. Bestätigte Zeiten und genehmigte Klärungen sind im Serverbestand gespeichert.</p>{/if}{#if resolvedReceipts.length}<details class="mt"><summary class="small">Zuletzt geklärte Originalaufzeichnungen ({resolvedReceipts.length})</summary>{#each resolvedReceipts.slice(-20) as receipt}<div class="sync-row"><Status value="resolved"/><p class="small mt">Aufgezeichnet: {displayTimestamp(receipt.occurred_at)}</p><p class="field-help">Freigegeben am {displayTimestamp(receipt.resolution?.approved_at)} · Korrekturbeleg {receipt.resolution?.correction_id}</p><details class="mt"><summary class="field-help">Unveränderte Rohaufzeichnung und Klärungsverweis</summary><pre class="json-preview mt">{JSON.stringify(receipt,null,2)}</pre></details></div>{/each}</details>{/if}{#if conflicts.length}<div class="notice warning mt"><Icon name="alert"/><div>Die Rohaufzeichnungen bleiben erhalten. Stellen Sie einen begründeten Korrekturantrag oder melden Sie sich erneut an. Klicken Sie nach der Freigabe auf „Synchronisieren“, um den Klärungsstand zu übernehmen.</div></div>{#each conflictGroups as sessionId}<button class="btn full mt" onclick={()=>openCorrection(conflictSource(sessionId))}>Aufzeichnungen vom {display(conflictSource(sessionId).started_at,'date')} klären</button>{/each}{/if}</div></section><section class="panel"><header class="panel-header"><h2>Mein Zeitkonto</h2></header><div class="panel-body"><dl class="definition-list"><div><dt>Freigegebene Stunden</dt><dd>{data.summary?.approvedHours??'—'}</dd></div><div><dt>Saldo</dt><dd>{data.summary?.timeBalance??'—'}</dd></div><div><dt>Urlaub verfügbar</dt><dd>{data.summary?.leaveBalance!=null?`${data.summary.leaveBalance} Tage`:'Nicht hinterlegt'}</dd></div>{#if data.summary?.timeBalanceAsOf}<div><dt>Saldo bis einschließlich</dt><dd>{display(data.summary.timeBalanceAsOf,'date')}</dd></div>{/if}<div><dt>Anträge</dt><dd><a class="text-link" href="/leave">Eigene Anträge<Icon name="arrow" size={14}/></a></dd></div></dl>{#if data.summary?.timeBalanceMessage}<p class="field-help mt">{data.summary.timeBalanceMessage}</p>{/if}</div></section><section class="panel"><header class="panel-header"><h2>Für unterwegs vorbereitet</h2></header><div class="panel-body"><p class="small">Auf diesem Gerät werden nur Ihre eigenen Zeitaufzeichnungen und die erforderlichen Auftragskurzangaben vorgehalten. Synchronisieren Sie nach einer Baustelle zeitnah.</p>{#if !storagePersistent}<button class="btn full mt" onclick={persist}><Icon name="lock" size={15}/>Browserspeicher anfragen</button>{:else}<p class="small mt">Der Browser hat dauerhaften Speicher gewährt.</p>{/if}<p class="field-help mt">Gelöschte Browserdaten können nicht wiederhergestellt werden. Ein geschlossener Browser garantiert keine Hintergrundübertragung.</p></div></section></aside></div>
{#if showManual}<div class="modal-backdrop" role="presentation"><div class="modal" role="dialog" use:focusTrap aria-modal="true" aria-labelledby="manual-title" tabindex="-1" onkeydown={(e)=>{if(e.key==='Escape'&&!busy)showManual=false;}}><header class="modal-header"><div><h2 id="manual-title">{showCorrection?'Korrekturantrag':'Zeit nachtragen'}</h2><p>Erfassen Sie den tatsächlichen Zeitraum. Auffälligkeiten werden zur Prüfung markiert.</p></div><button class="icon-button" onclick={()=>showManual=false} aria-label="Schließen" disabled={busy}><Icon name="close"/></button></header><form onsubmit={manual} style="display:contents"><div class="modal-body">{#if error}<div class="notice error" role="alert">{error}</div>{/if}<div class="field-grid"><div class="field"><label for="manual-from">Von *</label><input id="manual-from" type="datetime-local" step="1" bind:value={manualFrom} required/></div><div class="field"><label for="manual-to">Bis *</label><input id="manual-to" type="datetime-local" step="1" bind:value={manualTo} required/></div><div class="field full"><span class="field-label">Tatsächliche Pausen</span><p class="field-help">Tragen Sie jede genommene Pause mit Beginn und Ende ein. Falls Sie keine Pause genommen haben, lassen Sie die Liste leer und bestätigen Sie dies unten.</p>{#each manualPauses as pause,index}<div class="manual-pause"><div class="field"><label for={`pause-from-${pause.id}`}>Pause {index+1} von *</label><input id={`pause-from-${pause.id}`} type="datetime-local" step="1" bind:value={pause.from} required/></div><div class="field"><label for={`pause-to-${pause.id}`}>Bis *</label><input id={`pause-to-${pause.id}`} type="datetime-local" step="1" bind:value={pause.to} required/></div><button class="icon-button" type="button" aria-label={`Pause ${index+1} entfernen`} onclick={()=>manualPauses=manualPauses.filter(p=>p.id!==pause.id)}><Icon name="trash" size={16}/></button></div>{/each}<button type="button" class="btn" style="align-self:flex-start" onclick={()=>manualPauses=[...manualPauses,{id:crypto.randomUUID(),from:'',to:''}]}><Icon name="plus" size={15}/>Pause hinzufügen</button><label class="check-field mt"><input type="checkbox" bind:checked={pausesReviewed} required/><span>Ich habe alle tatsächlich genommenen Pausen vollständig angegeben.</span></label></div>{#if showCorrection&&manualAllocations.length}<section class="field full"><h3 style="font-size:16px;margin-top:8px">Arbeitszuordnungen dieser Sitzung</h3><p class="field-help">Die bisherigen Auftragswechsel bleiben einzeln sichtbar. Prüfen Sie die tatsächlichen Intervalle und passen Sie Zuordnungen nur bewusst an. Die Arbeitsintervalle müssen zur Sitzungszeit und zu den angegebenen Pausen passen.</p>{#each manualAllocations as allocation,index}<div class="manual-allocation"><div class="field-grid"><div class="field"><label for={`allocation-from-${allocation.id}`}>Arbeit {index+1} von *</label><input id={`allocation-from-${allocation.id}`} type="datetime-local" step="1" bind:value={allocation.from} required/></div><div class="field"><label for={`allocation-to-${allocation.id}`}>Bis *</label><input id={`allocation-to-${allocation.id}`} type="datetime-local" step="1" bind:value={allocation.to} required/></div><div class="field"><label for={`allocation-order-${allocation.id}`}>Auftrag</label><select id={`allocation-order-${allocation.id}`} bind:value={allocation.order_id}><option value="">Zuordnung offen</option>{#each orders as order}<option value={order.id}>{order.name}</option>{/each}</select></div><div class="field"><label for={`allocation-activity-${allocation.id}`}>Tätigkeit *</label><input id={`allocation-activity-${allocation.id}`} bind:value={allocation.activity} required/></div></div><button type="button" class="btn small mt" disabled={manualAllocations.length<=1} onclick={()=>manualAllocations=manualAllocations.filter(a=>a.id!==allocation.id)}>Arbeitsintervall entfernen</button></div>{/each}<button type="button" class="btn" onclick={()=>manualAllocations=[...manualAllocations,{id:crypto.randomUUID(),from:'',to:'',order_id:'',activity:''}]}><Icon name="plus" size={15}/>Arbeitsintervall hinzufügen</button></section>{:else}<div class="field"><label for="manual-order">Auftrag</label><select id="manual-order" bind:value={orderId}><option value="">Zuordnung offen</option>{#each orders as order}<option value={order.id}>{order.name}</option>{/each}</select></div>{/if}<div class="field full"><label for="manual-note">Tätigkeit / Grund der Nacherfassung *</label><textarea id="manual-note" bind:value={manualNote} required minlength="3"></textarea></div>{#if showCorrection}<div class="field full"><label for="correction-reason">Begründung *</label><textarea id="correction-reason" bind:value={correctionReason} required minlength="5"></textarea></div>{/if}</div></div><footer class="modal-footer"><button type="button" class="btn" onclick={()=>showManual=false} disabled={busy}>Abbrechen</button><button type="submit" class="btn primary" disabled={busy}>{busy?'Wird gespeichert …':showCorrection?'Antrag einreichen':'Zeitraum speichern'}</button></footer></form></div></div>{/if}
